{"path": "robot_name.py", "content": "import random
import string


class Robot:
    """A robot whose name is a unique random string like 'RX837'."""

    _used_names = set()

    def __init__(self):
        self.name = None
        self.reset()

    @classmethod
    def _generate_name(cls):
        if len(cls._used_names) >= 26 * 26 * 1000:
            raise RuntimeError("All robot names are in use")
        while True:
            name = "".join(random.choices(string.ascii_uppercase, k=2)) + "".join(
                random.choices(string.digits, k=3)
            )
            if name not in cls._used_names:
                cls._used_names.add(name)
                return name

    def reset(self):
        """Wipe the robot's name and assign a new unique random one."""
        old_name = self.name
        # Generate the new name while the old one is still reserved,
        # so the robot never gets its previous name back.
        self.name = self._generate_name()
        if old_name is not None:
            self._used_names.discard(old_name)
